int	char_to_base64(char c)
{
	if (c >= 'A' && c <= 'Z')
		c = c - 'A';
	else if (c >= 'a' && c <= 'z')
		c = c - 'a' + 26;
	else if (c >= '0' && c <= '9')
		c = c - '0' + 52;
	else if (c == '+')
		c = c - '+' + 62;
	else if (c == '-')
		c = c - '-' + 63;
	if (c == 47)
		c = 63;
	return (c);
}

